  local ok, dap = pcall(require, "dap")
  if not ok then
    return false
  end

  dap.configurations.python = {
    {
      type = "python",
      request = "launch",
      name = "Launch file",
      program = "${file}",
      pythonPath = function()
        local venv = vim.env.VIRTUAL_ENV
        if venv then
          if cross.is_windows() then
            return paths.join(venv, "Scripts", "python.exe")
          end
          return paths.join(venv, "bin", "python")
